 recv,ctrl,seq,raw=m.groups();raw=json.loads(raw)
 h,body=raw.split(' | '); hh=h.split()
 cs=[]
 for c in body.split(' ; '):
  words=c.split();head=next((w for w in words if '-' in w),None)
  cs.append({'head':head.split('-')[0] if head else None,'zone':ZONE_MARKERS[head.split('-')[1]] if head else None,'words':[w for w in words if w!=head and not is_number(w)],'n':next((parse_number(w) for w in words if is_number(w)),None)})
 frames.append(dict(recv=recv,ctrl=ctrl,seq=int(seq),tick=parse_number(hh[3]),clauses=cs,raw=raw))
