 if any(c['head']=='rote' and c['words']==['dika'] for c in f['clauses']):doors[f['zone']].add(f['t'])
for chan in ['badge_access','cctv_motion','forklift_telematics','probe_checks_sheet']:
 rows=list(csv.DictReader(open('/evidence/people/'+chan+'.csv')));scores=collections.Counter()
