zs={z:sorted([(f['t'],f['temp']) for f in fs if f['zone']==z and 'temp' in f]) for z in 'ABCDEF'}
res=[]
for off in range(-30,31):
 vals=collections.defaultdict(list)
 for r in rows:
  x,y=np.array(zs[r['zone']]).T;t=ts(r['device_timestamp'])-off
  vals[r['zone']].append(np.interp(t,x,y)-float(r['reading_c'])+(0.8 if r['handheld']=='HH-2' else 0))
 score=sum(sum((np.array(v)-np.mean(v))**2) for v in vals.values());res.append((score,off,{z:round(np.mean(v),3) for z,v in vals.items()}))
